func (s CameraJobServiceServer) Erase(ctx context.Context, req *api.CameraJobRef) (*api.CameraJobEraseResponse, error) {
	p, err := CameraJobPick(req)
	if err != nil {
		return nil, err
	}
	p, err = s.narrow(ctx, p)
	if err != nil {
		return nil, err
	}

	tx, err := ent1.JoinTx[*ent.Client, *ent.Tx](ctx, s.Db, s.Rec != nil)
	if err != nil {
		return nil, err
	}
	defer tx.Close()

	st := s
	st.Db = tx.Db

	var k any
	var previous *api.CameraJob
	if s.Rec != nil {
		images := snapshotOptions(s.Rec, api.CameraJobService_Erase_FullMethodName)
		var v *ent.CameraJob
		var err error
		if images.Previous {
			v, err = st.snapshot(ctx, p, true)
		} else {
			v, err = st.Db.CameraJob.Query().Where(p).Select(camerajob.FieldId).Only(ctx)
		}
		if err != nil {
			if ent.IsNotFound(err) {
				return &api.CameraJobEraseResponse{}, nil
			}
			return nil, err
		}

		k = v.Id
		if images.Previous {
			previous = s.image(v.Proto())
		}
		p = camerajob.And(p, camerajob.IdEQ(v.Id))
	}

	tx.Writing()
	u := st.Db.CameraJob.Update().Where(p)
	u.SetDateErased(st.now())
	u.SetDateUpdated(st.now())
	n, err := u.Save(ctx)
	if err != nil {
		return nil, err
	}
	if n > 0 {
		if err := record(ctx, s.Rec, st.Db, Change{
			By:       api.CameraJobService_Erase_FullMethodName,
			Key:      k,
			Previous: previous,
		}); err != nil {
			return nil, err
		}
	}
	if err := tx.Commit(); err != nil {
		return nil, err
	}
	res := &api.CameraJobEraseResponse{}
	res.SetErased(n > 0)

	return res, nil
}

// CameraJobPick answers with the predicate this reference selects on,
// among the rows that are still here.
//
// Erasure is part of the reference and not only part of a read's scope,
// because a reference to a CameraJob is composed into the reference of
// whatever names one: an index over an edge asks this for a predicate and
// puts it inside `HasCameraJobWith`, where no narrowing of a CameraJob
// is ever applied. A child of an erased row would otherwise be readable by
// naming its parent.
func CameraJobPick(req *api.CameraJobRef) (predicate.CameraJob, error) {
	p, err := pickCameraJob(req)
	if err != nil {
		return nil, err
	}

	return camerajob.And(camerajob.DateErasedIsNil(), p), nil
}

func pickCameraJob(req *api.CameraJobRef) (predicate.CameraJob, error) {
	switch req.WhichKey() {
	case api.CameraJobRef_Id_case:
		if v, err := entuuid.FromBytes(req.GetId()); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "id: %s", err)
		} else {
			return camerajob.IdEQ(v), nil
		}
	case api.CameraJobRef_Intent_case:
		k := req.GetIntent()
		ps := make([]predicate.CameraJob, 0, 2)
		if p, err := TenantPick(k.GetTenant()); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "intent.tenant: %s", err)
		} else {
			ps = append(ps, camerajob.HasTenantWith(p))
		}
		ps = append(ps, camerajob.RequestKeyEQ(k.GetRequestKey()))
		return camerajob.And(ps...), nil
	case api.CameraJobRef_Key_not_set_case:
		return nil, status.Errorf(codes.InvalidArgument, "key not set: CameraJob")
	default:
		return nil, status.Errorf(codes.Unimplemented, "unknown type of key: %s", req.WhichKey())
	}
}
